FILES={
    "web/index.html": '<!DOCTYPE html>\n<html lang="es">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width,initial-scale=1">\n<title>EGS | Academia Virtual de Bomberos</title>\n<link rel="stylesheet" href="styles.css">\n</head>\n<body>\n<header class="topbar">\n  <div>\n    <div class="brand">EGS | ACADEMIA VIRTUAL DE BOMBEROS</div>\n    <div class="subtitle">Centro de Investigación, Simulación y Entrenamiento Bomberil</div>\n  </div>\n  <nav class="topnav">\n    <button onclick="goHome()">Campus</button>\n    <button onclick="openAcademy()">Academia</button>\n    <button onclick="openSimulator()">Simulador 3D</button>\n    <button onclick="showSources()">Biblioteca</button>\n  </nav>\n  <div class="status" id="apiStatus">RC 1.1.1 · CARGANDO</div>\n</header>\n\n<main>\n<section id="home" class="screen active">\n  <p class="eyebrow">CAMPUS DE ENTRENAMIENTO BOMBERIL</p>\n  <h1>Academia Virtual de Bomberos</h1>\n  <p class="lead">Estudio, evaluación y simulación 3D interactiva con trazabilidad doctrinaria.</p>\n  <div class="stats">\n    <div><span>MÓDULOS</span><strong id="moduleCount">8</strong></div>\n    <div><span>EVALUACIONES</span><strong id="completedCount">0</strong></div>\n    <div><span>MEJOR PUNTAJE</span><strong id="bestScore">—</strong></div>\n    <div><span>INTENTOS</span><strong id="attemptCount">0</strong></div>\n  </div>\n  <div class="heroActions">\n    <button class="primary" onclick="openAcademy()">IR A LA ACADEMIA</button>\n    <button class="secondary" onclick="startIntegral()">EVALUACIÓN INTEGRAL</button>\n    <button class="secondary" onclick="openSimulator()">SIMULADOR 3D</button>\n  </div>\n  <div class="searchBox"><input id="globalSearch" placeholder="Buscar módulo o tema..." oninput="searchContent(this.value)"></div>\n  <div id="searchResults" class="grid"></div>\n</section>\n\n<section id="academy" class="screen">\n  <button class="back" onclick="goHome()">← Campus principal</button>\n  <p class="eyebrow">PROGRAMA DE FORMACIÓN</p>\n  <h1>Academia</h1>\n  <div id="academyGrid" class="grid"></div>\n</section>\n\n<section id="module" class="screen">\n  <button class="back" onclick="openAcademy()">← Academia</button>\n  <p class="eyebrow" id="moduleStatus">MÓDULO</p>\n  <h1 id="moduleTitle">Módulo</h1>\n  <div class="moduleBar"><span id="moduleSourceCount">0 fuentes</span><span id="moduleQuestionCount">0 preguntas</span></div>\n  <div id="moduleSections" class="grid"></div>\n  <button id="moduleTrainingButton" class="primary">INICIAR EVALUACIÓN</button>\n</section>\n\n<section id="sources" class="screen">\n  <button class="back" onclick="goHome()">← Campus principal</button>\n  <p class="eyebrow">TRAZABILIDAD</p>\n  <h1>Biblioteca Doctrinaria</h1>\n  <div id="sourceList" class="grid"></div>\n</section>\n\n<section id="simulator" class="screen simulatorScreen">\n  <div class="simTop">\n    <div>\n      <button class="back" onclick="goHome()">← Campus principal</button>\n      <p class="eyebrow">SIMULADOR OPERACIONAL 3D</p>\n      <h1 id="simScenarioTitle">Selección de escenario</h1>\n    </div>\n    <div class="simTopActions">\n      <select id="simScenarioSelect">\n        <option value="house">Incendio en vivienda unifamiliar</option>\n        <option value="apartment">Incendio en departamento</option>\n        <option value="warehouse">Incendio en depósito</option>\n        <option value="vehicle_fire">Incendio vehicular</option>\n        <option value="vehicle_rescue">Rescate vehicular con atrapado</option>\n        <option value="phenomena">Laboratorio de fenómenos</option>\n      </select>\n      <select id="simCameraSelect">\n        <option value="orbit">Cámara orbital</option>\n        <option value="first">Primera persona</option>\n      </select>\n      <select id="qualitySelect">\n        <option value="baja">Calidad baja</option>\n        <option value="media" selected>Calidad media</option>\n        <option value="alta">Calidad alta</option>\n      </select>\n      <button class="secondary" id="simResetBtn">REINICIAR</button>\n    </div>\n  </div>\n\n  <div class="briefing" id="simBriefing">\n    Elegí un escenario. Cada acción modifica el entorno, la telemetría y el resultado.\n  </div>\n\n  <div class="simShell">\n    <div class="simViewportWrap">\n      <div id="sim3d"><div class="loading3d">Cargando motor 3D...</div></div>\n      <div class="simHUD topLeft"><span>TIEMPO</span><strong id="simClock">00:00</strong></div>\n      <div class="simHUD topRight"><span>OBJETIVO</span><strong id="simObjective">Reconocimiento inicial</strong></div>\n      <div class="crosshair">+</div>\n    </div>\n\n    <aside class="simPanel">\n      <div class="panelSection">\n        <span class="panelLabel">ESTADO DE ESCENA</span>\n        <div class="meterRow"><span>Temperatura</span><strong id="simTemp">—</strong></div>\n        <div class="meterRow"><span>Humo</span><strong id="simSmoke">—</strong></div>\n        <div class="meterRow"><span>Visibilidad</span><strong id="simVisibility">—</strong></div>\n        <div class="meterRow"><span>Oxígeno</span><strong id="simOxygen">—</strong></div>\n        <div class="meterRow"><span>Puntaje</span><strong id="simScore">100</strong></div>\n      </div>\n\n      <div class="panelSection">\n        <span class="panelLabel">ACCIONES</span>\n        <div id="simActions"></div>\n      </div>\n\n      <div class="panelSection">\n        <span class="panelLabel">REGISTRO</span>\n        <div id="simLog" class="simLog"></div>\n      </div>\n\n      <button class="primary full" id="simFinishBtn">FINALIZAR SIMULACIÓN</button>\n    </aside>\n  </div>\n\n  <p class="simNotice">Simulación educativa en tiempo real. Representa consecuencias operativas mediante reglas y visualización 3D; no sustituye entrenamiento práctico ni constituye CFD certificado.</p>\n</section>\n\n<section id="training" class="screen">\n  <div class="trainingHead"><div><p class="eyebrow">ENTRENAMIENTO ACTIVO</p><h1 id="trainingTitle">Entrenamiento</h1></div><div class="scoreMini">PUNTAJE<strong id="liveScore">100</strong></div></div>\n  <div class="trainingLayout">\n    <div class="scenarioPanel">\n      <div class="telemetry"><div><span>TIEMPO</span><strong id="time">00:00</strong></div><div><span>PREGUNTA</span><strong id="stepCounter">1/1</strong></div><div><span>FUENTE</span><strong id="sourceBadge">—</strong></div></div>\n      <div class="sceneMock"><div class="smoke"></div><div class="structure"></div></div>\n    </div>\n    <aside class="decisionPanel"><span class="panelLabel">DECISIÓN / CONOCIMIENTO</span><h2 id="question">Cargando...</h2><div id="options"></div><div id="feedback"></div><button class="finish" onclick="finishTraining()">FINALIZAR</button></aside>\n  </div>\n</section>\n\n<section id="analysis" class="screen">\n  <p class="eyebrow">INFORME POST ENTRENAMIENTO</p><h1>Análisis posterior</h1>\n  <div class="analysisTop"><div class="finalScore"><strong id="finalScore">100</strong><span>/100</span></div><div id="analysisSummary"></div></div>\n  <div id="decisionLog" class="report"></div>\n  <div class="heroActions"><button class="primary" onclick="goHome()">VOLVER AL CAMPUS</button><button class="secondary" onclick="exportResult()">EXPORTAR RESULTADO</button></div>\n</section>\n</main>\n\n<footer>\n  <div><strong>EGS | Estudio de Gestión de Sistemas</strong><span>Academia Virtual de Bomberos</span></div>\n  <div class="credit"><span>Desarrollado por</span><strong>Téc. Sup. en Gestión Ambiental Yamila Vocos</strong><span>San Francisco, Córdoba · Argentina</span></div>\n  <div class="right"><span>RC 1.1.1 · 2026</span><span>Doctrina versionada y sujeta a revisión</span></div>\n</footer>\n\n<script src="app.js?v=111"></script>\n</body>\n</html>\n',
    "web/app.js": 'const API_URL="http://127.0.0.1:8001";\nlet cache={academy:null,sources:null};let activeModule=null,activeTraining=[],activeMeta=null,current=0,score=100,log=[],timer=null,seconds=0,lastResult=null;\nfunction showScreen(id){document.querySelectorAll(".screen").forEach(x=>x.classList.remove("active"));document.getElementById(id)?.classList.add("active");window.scrollTo(0,0)}\nfunction goHome(){stopTimer();showScreen("home");updateCampus()}\nasync function api(path){const r=await fetch(API_URL+path);if(!r.ok)throw new Error("HTTP "+r.status);return r.json()}\nfunction txt(v){return String(v??"")}\nfunction getProgress(){try{return JSON.parse(localStorage.getItem("egs_bomberos_progress"))||{intentos:0,mejor_puntaje:null,evaluaciones_completadas:0,por_modulo:{}}}catch(e){return {intentos:0,mejor_puntaje:null,evaluaciones_completadas:0,por_modulo:{}}}}\nfunction saveProgress(p){localStorage.setItem("egs_bomberos_progress",JSON.stringify(p));updateCampus()}\nfunction updateCampus(){const p=getProgress();document.getElementById("moduleCount").textContent=cache.academy?.modules?.length||8;document.getElementById("completedCount").textContent=p.evaluaciones_completadas||0;document.getElementById("bestScore").textContent=p.mejor_puntaje==null?"—":p.mejor_puntaje;document.getElementById("attemptCount").textContent=p.intentos||0}\nasync function boot(){try{const s=await api("/");document.getElementById("apiStatus").textContent=`RC 1.1 · ${txt(s.status).toUpperCase()}`;[cache.academy,cache.sources]=await Promise.all([api("/academy/modules"),api("/sources")]);updateCampus()}catch(e){document.getElementById("apiStatus").textContent="RC 1.1 · API DESCONECTADA";console.warn(e)}}\nasync function openAcademy(){if(!cache.academy)cache.academy=await api("/academy/modules");document.getElementById("academyGrid").innerHTML=cache.academy.modules.map(m=>`<article class="tile clickable" onclick="openModule(\'${m.id}\')"><span>${txt(m.area)}</span><h2>${txt(m.name)}</h2><p>${txt(m.description)}</p><span class="moduleStatus">${txt(m.status).toUpperCase()}</span></article>`).join("");showScreen("academy")}\nasync function openModule(id){activeModule=await api(`/academy/module/${id}`);activeModule._id=id;document.getElementById("moduleTitle").textContent=activeModule.metadata?.module_name||id;document.getElementById("moduleStatus").textContent=(activeModule.metadata?.status||"módulo").toUpperCase();document.getElementById("moduleSourceCount").textContent=`${(activeModule.metadata?.source_ids||[]).length} fuentes`;document.getElementById("moduleQuestionCount").textContent=`${(activeModule.training||[]).length} preguntas`;document.getElementById("moduleSections").innerHTML=(activeModule.sections||[]).map(s=>`<article class="tile"><h2>${txt(s.title)}</h2><p>${txt(s.summary||s.concepts?.join(" · "))}</p><span class="moduleStatus">${txt(s.source_id||"")}</span></article>`).join("");const b=document.getElementById("moduleTrainingButton");b.style.display=(activeModule.training||[]).length?"inline-block":"none";b.onclick=()=>startTraining(id);showScreen("module")}\nasync function showSources(){if(!cache.sources)cache.sources=await api("/sources");document.getElementById("sourceList").innerHTML=cache.sources.sources.map(s=>`<article class="sourceCard"><strong>${txt(s.title)}</strong><p>${txt(s.organization)}</p><p>Estado: ${txt(s.status)}</p><p>Rol: ${txt(s.role)}</p></article>`).join("");showScreen("sources")}\nasync function startTraining(id){const d=await api(`/academy/module/${id}/training?shuffle=true`);runTraining(d,id)}\nasync function startIntegral(){const d=await api("/academy/integral?limit=20");runTraining(d,"integral")}\nfunction runTraining(d,id){activeTraining=d.training||[];activeMeta=d.metadata||{};activeMeta._id=id;current=0;score=100;log=[];seconds=0;const p=getProgress();p.intentos=(p.intentos||0)+1;saveProgress(p);document.getElementById("trainingTitle").textContent=activeMeta.module_name||"Entrenamiento";document.getElementById("liveScore").textContent=score;showScreen("training");renderStep();startTimer()}\nfunction renderStep(){const s=activeTraining[current];if(!s){finishTraining();return}document.getElementById("question").textContent=s.question;document.getElementById("stepCounter").textContent=`${current+1}/${activeTraining.length}`;document.getElementById("sourceBadge").textContent=s.source_id||"—";document.getElementById("feedback").innerHTML="";const opts=(s.options||[]).slice().sort(()=>Math.random()-.5);document.getElementById("options").innerHTML=opts.map((o,i)=>`<button class="optionBtn" data-i="${i}">${txt(o.text)}</button>`).join("");document.querySelectorAll(".optionBtn").forEach(b=>b.onclick=()=>choose(opts[Number(b.dataset.i)]))}\nfunction choose(o){score=Math.max(0,Math.min(100,score+Number(o.score||0)));document.getElementById("liveScore").textContent=score;const st=o.status==="correct"?"Adecuada":o.status==="critical_error"?"Error crítico":"Requiere revisión";log.push({n:current+1,text:o.text,status:st,impact:Number(o.score||0),source:activeTraining[current].source_id,module:activeTraining[current].module_name||activeMeta.module_name});document.getElementById("feedback").innerHTML=`<div class="feedbackBox"><strong>${st}</strong><br>${o.status==="correct"?"Respuesta coherente con la fuente cargada.":"Revisar el fundamento doctrinario en el análisis posterior."}</div>`;document.querySelectorAll(".optionBtn").forEach(b=>b.disabled=true);current++;setTimeout(renderStep,700)}\nfunction startTimer(){stopTimer();timer=setInterval(()=>{seconds++;document.getElementById("time").textContent=`${String(Math.floor(seconds/60)).padStart(2,"0")}:${String(seconds%60).padStart(2,"0")}`},1000)}\nfunction stopTimer(){if(timer){clearInterval(timer);timer=null}}\nfunction finishTraining(){stopTimer();document.getElementById("finalScore").textContent=score;const p=getProgress();p.evaluaciones_completadas=(p.evaluaciones_completadas||0)+1;p.mejor_puntaje=p.mejor_puntaje==null?score:Math.max(p.mejor_puntaje,score);saveProgress(p);document.getElementById("decisionLog").innerHTML=log.map(x=>`<div class="entry"><strong>${x.n}. ${txt(x.status)}</strong><p>${txt(x.text)}</p><p>Impacto ${x.impact} · Fuente ${txt(x.source)}</p></div>`).join("");lastResult={fecha:new Date().toISOString(),modulo:activeMeta.module_name,puntaje:score,decisiones:log};showScreen("analysis")}\nfunction exportResult(){if(!lastResult)return;const blob=new Blob([JSON.stringify(lastResult,null,2)],{type:"application/json"});const a=document.createElement("a");a.href=URL.createObjectURL(blob);a.download=`egs_resultado_${Date.now()}.json`;a.click();URL.revokeObjectURL(a.href)}\nasync function searchContent(q){const box=document.getElementById("searchResults");q=q.trim().toLowerCase();if(q.length<2){box.innerHTML="";return}if(!cache.academy)cache.academy=await api("/academy/modules");let results=[];for(const m of cache.academy.modules){if((m.name+" "+m.description+" "+m.area).toLowerCase().includes(q))results.push({type:"Módulo",title:m.name,id:m.id,desc:m.description});try{const d=await api(`/academy/module/${m.id}`);for(const s of d.sections||[]){if((s.title+" "+s.summary).toLowerCase().includes(q))results.push({type:"Tema",title:s.title,id:m.id,desc:m.name})}}catch(e){}}box.innerHTML=results.slice(0,12).map(r=>`<article class="tile clickable" onclick="openModule(\'${r.id}\')"><span>${r.type}</span><h2>${txt(r.title)}</h2><p>${txt(r.desc)}</p></article>`).join("")}\n\n/* ===== SIMULADOR ===== */\nlet egs3dPromise=null;\nasync function loadEGS3D(){\n  if(window.EGS3D)return window.EGS3D;\n  if(egs3dPromise)return egs3dPromise;\n  document.getElementById("sim3d").innerHTML=\'<div class="loading3d">Cargando motor 3D...</div>\';\n  egs3dPromise=import("./simulator.js?v=111").then(()=>{if(!window.EGS3D)throw new Error("El motor no registró EGS3D");return window.EGS3D}).catch(err=>{document.getElementById("sim3d").innerHTML=\'<div class="loading3d">Error cargando 3D: \'+String(err.message||err)+\'</div>\';egs3dPromise=null;throw err});\n  return egs3dPromise;\n}\nasync function openSimulator(){\n  showScreen("simulator");\n  wireSimulatorUI();\n  try{\n    const e=await loadEGS3D();\n    await e.init();\n    const selected=document.getElementById("simScenarioSelect")?.value||"house";\n    e.setScenario(selected);\n    e.start();\n  }catch(err){\n    console.error("EGS SIMULADOR:",err);\n    const target=document.getElementById("sim3d");\n    if(target) target.innerHTML=\'<div class="loading3d" style="color:#ff9a78;text-align:center;padding:30px">No se pudo iniciar el motor 3D.<br><br>\'+String(err.message||err)+\'<br><br>Probá Ctrl + Shift + R y verificá Internet.</div>\';\n  }\n}\nfunction wireSimulatorUI(){\n  const scenario=document.getElementById("simScenarioSelect"),camera=document.getElementById("simCameraSelect"),quality=document.getElementById("qualitySelect");\n  scenario.onchange=async()=>{\n    renderSimActions(scenario.value);\n    try{const e=await loadEGS3D();await e.init();e.setScenario(scenario.value)}catch(err){console.error(err)}\n  }\n  camera.onchange=async()=>{const e=await loadEGS3D();e.setCameraMode(camera.value)}\n  quality.onchange=async()=>{const e=await loadEGS3D();e.setQuality(quality.value)}\n  document.getElementById("simResetBtn").onclick=async()=>{(await loadEGS3D()).reset()}\n  document.getElementById("simFinishBtn").onclick=async()=>{(await loadEGS3D()).finish()}\n  renderSimActions(scenario.value)\n}\nfunction renderSimActions(id){\n  const common=[["recognition","Reconocimiento 360°"],["open_access","Abrir acceso"],["cooling","Aplicar agua / enfriamiento"],["search","Iniciar búsqueda"]];\n  const map={\n    house:common.concat([["open_window","Abrir ventana"],["ventilate","Ventilar"]]),\n    apartment:common.concat([["open_window","Abrir ventana"],["ventilate","Ventilar"]]),\n    warehouse:common.concat([["protect_exposure","Proteger exposición"]]),\n    vehicle_fire:[["recognition","Reconocimiento 360°"],["isolate","Aislar vehículo"],["cooling","Aplicar enfriamiento"],["attack_vehicle","Atacar foco"]],\n    vehicle_rescue:[["recognition","Evaluar escena"],["isolate","Aislar riesgos"],["stabilize","Estabilizar vehículo"],["access_victim","Crear acceso"],["extricate","Extricar víctima"]],\n    phenomena:[["phen_rollover","Rollover"],["phen_flashover","Flashover"],["phen_backdraft","Backdraft / ventilación súbita"],["phen_smoke","Explosión de humo (visual educativa)"]]\n  };\n  document.getElementById("simActions").innerHTML=(map[id]||common).map(x=>`<button class="actionBtn" onclick="simAction(\'${x[0]}\')">${x[1]}</button>`).join("")\n}\nasync function simAction(a){(await loadEGS3D()).action(a)}\ndocument.addEventListener("DOMContentLoaded",boot);\n',
    "web/simulator.js": 'let THREE = null;\nasync function loadThreeEngine(){\n  if(THREE) return THREE;\n  let firstError = null;\n  try{\n    THREE = await import("https://esm.sh/three@0.180.0");\n    console.log("EGS 3D: Three.js cargado desde esm.sh");\n    return THREE;\n  }catch(err){\n    firstError = err;\n    console.warn("EGS 3D: esm.sh falló, probando jsDelivr", err);\n  }\n  try{\n    THREE = await import("https://cdn.jsdelivr.net/npm/three@0.180.0/build/three.module.js");\n    console.log("EGS 3D: Three.js cargado desde jsDelivr");\n    return THREE;\n  }catch(err2){\n    console.error("EGS 3D: fallaron ambos proveedores", firstError, err2);\n    throw new Error("No se pudo cargar Three.js desde esm.sh ni jsDelivr. Verificá conexión a Internet.");\n  }\n}\n\nconst SCENARIOS={\nhouse:{name:"Incendio en vivienda unifamiliar",brief:"Vivienda de una planta con foco en cocina, humo interior y una víctima.",state:{temperature:120,smoke:35,visibility:72,oxygen:20.2,score:100}},\napartment:{name:"Incendio en departamento",brief:"Departamento compartimentado, foco interior y ventilación limitada.",state:{temperature:160,smoke:48,visibility:58,oxygen:19.5,score:100}},\nwarehouse:{name:"Incendio en depósito",brief:"Depósito con carga combustible, gran volumen y exposición interna.",state:{temperature:190,smoke:42,visibility:64,oxygen:19.9,score:100}},\nvehicle_fire:{name:"Incendio vehicular",brief:"Vehículo liviano con fuego en sector motor y producción intensa de humo.",state:{temperature:240,smoke:45,visibility:62,oxygen:20.4,score:100}},\nvehicle_rescue:{name:"Rescate vehicular con atrapado",brief:"Colisión de vehículo liviano con víctima atrapada. Requiere asegurar, estabilizar, acceder y extricar.",state:{temperature:28,smoke:0,visibility:100,oxygen:20.9,score:100}},\nphenomena:{name:"Laboratorio de fenómenos",brief:"Entorno demostrativo para visualizar cambios bruscos del comportamiento del incendio.",state:{temperature:190,smoke:52,visibility:50,oxygen:18.5,score:100}}\n};\nconst QUALITY={baja:{particles:80,pixel:1},media:{particles:150,pixel:1.1},alta:{particles:260,pixel:1.25}};\nlet scene,camera,renderer,container,active="house",state={},objects={},fires=[],smoke=[],water=[],running=false,elapsed=0,last=0,quality="media",mode="orbit";\nlet orbit={drag:false,lx:0,ly:0,yaw:.72,pitch:.48,radius:20},fp={x:0,y:1.65,z:9,yaw:Math.PI,pitch:0},keys={};\n\nfunction $(id){return document.getElementById(id)}function fmt(s){return `${String(Math.floor(s/60)).padStart(2,"0")}:${String(Math.floor(s%60)).padStart(2,"0")}`}\nfunction mat(c,r=.85){return new THREE.MeshStandardMaterial({color:c,roughness:r})}\nfunction box(parent,size,pos,m,name=""){const x=new THREE.Mesh(new THREE.BoxGeometry(...size),m);x.position.set(...pos);x.name=name;x.castShadow=true;x.receiveShadow=true;parent.add(x);return x}\nfunction log(t){const b=$("simLog");if(!b)return;const d=document.createElement("div");d.textContent=`${fmt(elapsed)} · ${t}`;b.prepend(d);while(b.children.length>14)b.removeChild(b.lastChild)}\nfunction hud(){if($("simClock"))$("simClock").textContent=fmt(elapsed);if($("simTemp"))$("simTemp").textContent=`${Math.round(state.temperature)} °C`;if($("simSmoke"))$("simSmoke").textContent=`${Math.round(state.smoke)} %`;if($("simVisibility"))$("simVisibility").textContent=`${Math.round(state.visibility)} %`;if($("simOxygen"))$("simOxygen").textContent=`${state.oxygen.toFixed(1)} %`;if($("simScore"))$("simScore").textContent=Math.max(0,Math.min(100,Math.round(state.score)));if($("simScenarioTitle"))$("simScenarioTitle").textContent=SCENARIOS[active].name;if($("simBriefing"))$("simBriefing").textContent=SCENARIOS[active].brief}\nfunction fire(pos,s=1){const g=new THREE.Group();g.position.set(...pos);g.scale.setScalar(s);scene.add(g);fires.push(g);for(let i=0;i<14;i++){const f=new THREE.Mesh(new THREE.ConeGeometry(.11+Math.random()*.12,.45+Math.random()*.5,7),new THREE.MeshStandardMaterial({color:i%2?0xff6500:0xffc244,emissive:i%2?0xff2e00:0xff8a00,emissiveIntensity:2.2,transparent:true,opacity:.9}));f.position.set((Math.random()-.5)*1.1,Math.random()*.35,(Math.random()-.5)*.8);g.add(f)}const l=new THREE.PointLight(0xff5b18,6.5,7,2);l.position.y=1;g.add(l)}\nfunction smokeTex(){const c=document.createElement("canvas");c.width=c.height=64;const x=c.getContext("2d"),g=x.createRadialGradient(32,32,3,32,32,30);g.addColorStop(0,"rgba(70,70,70,.5)");g.addColorStop(.6,"rgba(45,45,45,.2)");g.addColorStop(1,"rgba(20,20,20,0)");x.fillStyle=g;x.fillRect(0,0,64,64);return new THREE.CanvasTexture(c)}\nfunction smokeCloud(o,sp){const tex=smokeTex();for(let i=0;i<QUALITY[quality].particles;i++){const s=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,opacity:.2,depthWrite:false}));s.position.set(o[0]+Math.random()*sp[0],o[1]+Math.random()*sp[1],o[2]+Math.random()*sp[2]);const k=.55+Math.random()*1.5;s.scale.set(k,k,k);s.userData.speed=.06+Math.random()*.08;scene.add(s);smoke.push(s)}}\nfunction victim(pos){const v=new THREE.Mesh(new THREE.CapsuleGeometry(.28,.9,4,8),mat(0x1f2327));v.position.set(...pos);v.rotation.z=Math.PI/2;scene.add(v);objects.victim=v}\nfunction vehicle(color=0x8f1f1f){const g=new THREE.Group();scene.add(g),body=mat(color,.65),dark=mat(0x15181a,.8);objects.vehicle=box(g,[4.2,.9,1.9],[0,.85,0],body);box(g,[2.3,.8,1.75],[-.2,1.55,0],body);for(const x of [-1.45,1.45])for(const z of [-.92,.92]){const w=new THREE.Mesh(new THREE.CylinderGeometry(.38,.38,.28,18),dark);w.rotation.x=Math.PI/2;w.position.set(x,.45,z);g.add(w)}return g}\nfunction houseBase(){const g=new THREE.Group();scene.add(g),wall=mat(0xc8b8a2,.96),floor=mat(0x4b4d4f,.98),wood=mat(0x5a3b27,.9);box(g,[12,.25,9],[0,0,0],floor);box(g,[12,3.2,.22],[0,1.7,-4.4],wall);box(g,[.22,3.2,9],[-5.9,1.7,0],wall);box(g,[.22,3.2,9],[5.9,1.7,0],wall);box(g,[3.6,3.2,.22],[-4.1,1.7,4.4],wall);box(g,[2.1,3.2,.22],[-.7,1.7,4.4],wall);box(g,[3.3,3.2,.22],[4.25,1.7,4.4],wall);box(g,[.22,3,5.4],[.8,1.6,-1.3],wall);box(g,[4.8,3,.22],[-3.35,1.6,-1.2],wall);objects.door=box(g,[1.2,2.3,.12],[1.2,1.2,4.28],wood);objects.window=box(g,[2,1.35,.08],[-2.15,1.9,4.28],new THREE.MeshStandardMaterial({color:0x77a9bd,transparent:true,opacity:.45}));box(g,[2.7,.85,1],[-2.2,.55,1],mat(0x51463f));box(g,[2.5,.55,3.1],[-3.5,.42,-2.7],mat(0xb8aaa0));box(g,[3.5,.95,.65],[3.6,.55,-3.7],mat(0x666a6d))}\nfunction clear(){fires=[];smoke=[];water=[];objects={};while(scene.children.length)scene.remove(scene.children[0]);scene.background=new THREE.Color(0x10161c);scene.fog=new THREE.FogExp2(0x2c3236,.018);scene.add(new THREE.HemisphereLight(0xcfe5f7,0x221b17,2));const sun=new THREE.DirectionalLight(0xffefd4,2.7);sun.position.set(-8,14,10);scene.add(sun);const ground=new THREE.Mesh(new THREE.BoxGeometry(40,.25,34),mat(0x283329,1));ground.position.y=-.25;scene.add(ground)}\nfunction build(){\n clear();state=JSON.parse(JSON.stringify(SCENARIOS[active].state));elapsed=0;\n if(active==="house"){houseBase();victim([-3.6,.62,-2.8]);fire([3.8,.35,-3.2],1);smokeCloud([2,1.3,-4],[4.5,2.2,5.2])}\n if(active==="apartment"){houseBase();box(scene,[12,.18,9],[0,3.45,0],mat(0x54575b));victim([-3,.62,-2]);fire([-2.5,.4,1.4],.9);smokeCloud([-4,1.2,-1],[5,2.3,6])}\n if(active==="warehouse"){const g=new THREE.Group();scene.add(g),w=mat(0x8e9499,.92);box(g,[18,.25,12],[0,0,0],mat(0x414448,.98));box(g,[18,5,.25],[0,2.6,-5.8],w);box(g,[.25,5,12],[-8.9,2.6,0],w);box(g,[.25,5,12],[8.9,2.6,0],w);for(let x=-6;x<=6;x+=4)for(let z=-3;z<=2;z+=2.5)box(g,[2.2,2.2,1.4],[x,1.1,z],mat(0x6c4e2f));fire([4,.4,-2],1.3);fire([5.2,.4,-2.4],.8);smokeCloud([0,1.5,-5],[14,3,7])}\n if(active==="vehicle_fire"){vehicle();fire([1.5,.55,0],1);smokeCloud([.8,1.4,-1.5],[4,2.5,3.2])}\n if(active==="vehicle_rescue"){vehicle(0x2f5d8c);objects.vehicle.rotation.y=.18;victim([-.3,1.1,0]);box(scene,[1.6,.25,.8],[2.2,.15,0],mat(0xe8a531))}\n if(active==="phenomena"){const g=new THREE.Group();scene.add(g),w=mat(0xa99c8d,.95);box(g,[10,.25,8],[0,0,0],mat(0x46494c));box(g,[10,3.4,.22],[0,1.8,-3.9],w);box(g,[.22,3.4,8],[-4.9,1.8,0],w);box(g,[.22,3.4,8],[4.9,1.8,0],w);box(g,[3.2,3.4,.22],[-3.4,1.8,3.9],w);box(g,[3.2,3.4,.22],[3.4,1.8,3.9],w);objects.door=box(g,[1.3,2.4,.12],[0,1.25,3.82],mat(0x503627));fire([0,.35,-2.4],.9);smokeCloud([-4,1.4,-3],[8,2.4,6])}\n hud();log("Escenario cargado")\n}\nfunction resize(){const r=container.getBoundingClientRect();renderer.setSize(Math.max(320,r.width),Math.max(420,r.height),false);camera.aspect=Math.max(320,r.width)/Math.max(420,r.height);camera.updateProjectionMatrix()}\nfunction orbitCam(){orbit.pitch=Math.max(.14,Math.min(1.25,orbit.pitch));orbit.radius=Math.max(5,Math.min(34,orbit.radius));camera.position.set(orbit.radius*Math.cos(orbit.pitch)*Math.cos(orbit.yaw),1.2+orbit.radius*Math.sin(orbit.pitch),orbit.radius*Math.cos(orbit.pitch)*Math.sin(orbit.yaw));camera.lookAt(0,1.2,0)}\nfunction controls(){renderer.domElement.addEventListener("pointerdown",e=>{if(mode!=="orbit")return;orbit.drag=true;orbit.lx=e.clientX;orbit.ly=e.clientY});renderer.domElement.addEventListener("pointerup",()=>orbit.drag=false);renderer.domElement.addEventListener("pointermove",e=>{if(mode==="orbit"&&orbit.drag){orbit.yaw-=(e.clientX-orbit.lx)*.008;orbit.pitch-=(e.clientY-orbit.ly)*.006;orbit.lx=e.clientX;orbit.ly=e.clientY;orbitCam()}if(mode==="first"&&document.pointerLockElement===renderer.domElement){fp.yaw-=e.movementX*.0025;fp.pitch-=e.movementY*.0022;fp.pitch=Math.max(-1.2,Math.min(1.2,fp.pitch))}});renderer.domElement.addEventListener("wheel",e=>{if(mode!=="orbit")return;e.preventDefault();orbit.radius+=e.deltaY*.012;orbitCam()},{passive:false});renderer.domElement.addEventListener("click",()=>{if(mode==="first")renderer.domElement.requestPointerLock?.()});window.addEventListener("keydown",e=>keys[e.code]=true);window.addEventListener("keyup",e=>keys[e.code]=false);orbitCam()}\nfunction fpMove(dt){if(mode!=="first")return;const speed=3*dt,dir=new THREE.Vector3(Math.sin(fp.yaw),0,Math.cos(fp.yaw)),right=new THREE.Vector3(dir.z,0,-dir.x);if(keys.KeyW){fp.x+=dir.x*speed;fp.z+=dir.z*speed}if(keys.KeyS){fp.x-=dir.x*speed;fp.z-=dir.z*speed}if(keys.KeyA){fp.x-=right.x*speed;fp.z-=right.z*speed}if(keys.KeyD){fp.x+=right.x*speed;fp.z+=right.z*speed}camera.position.set(fp.x,fp.y,fp.z);const look=new THREE.Vector3(Math.sin(fp.yaw)*Math.cos(fp.pitch),Math.sin(fp.pitch),Math.cos(fp.yaw)*Math.cos(fp.pitch));camera.lookAt(camera.position.clone().add(look))}\nfunction waterBurst(){for(let i=0;i<100;i++){const p=new THREE.Mesh(new THREE.SphereGeometry(.025,5,4),new THREE.MeshBasicMaterial({color:0x79c7ff}));p.position.set(0,1.2,2.5);p.userData.v=new THREE.Vector3((Math.random()-.5)*.8,.1+Math.random()*.25,-3-Math.random()*2);scene.add(p);water.push(p)}}\nfunction animate(now){requestAnimationFrame(animate);const dt=Math.min(.05,last?(now-last)/1000:0);last=now;if(running){elapsed+=dt;fires.forEach((g,gi)=>g.children.forEach((f,i)=>{if(f.isMesh)f.scale.y=.8+Math.sin(now*.012+i+gi)*.18+Math.random()*.08}));smoke.forEach(s=>{s.position.y+=s.userData.speed*dt;if(s.position.y>4.8)s.position.y=1.3;s.material.opacity=Math.min(.34,.1+state.smoke/450)});water.forEach((p,i)=>{p.position.addScaledVector(p.userData.v,dt);p.userData.v.y-=1.2*dt;if(p.position.y<0){scene.remove(p);water.splice(i,1)}});if(active!=="vehicle_rescue"){state.temperature=Math.min(850,state.temperature+.3*dt);state.smoke=Math.min(100,state.smoke+.08*dt);state.visibility=Math.max(4,state.visibility-.05*dt);state.oxygen=Math.max(12,state.oxygen-.004*dt)}hud()}fpMove(dt);renderer.render(scene,camera)}\nasync function init(){\n  container=$("sim3d");\n  if(!container) throw new Error("No existe el contenedor del simulador.");\n  if(renderer){resize();return}\n  container.innerHTML=\'<div class="loading3d">Inicializando motor 3D...</div>\';\n  THREE = await loadThreeEngine();\n  scene=new THREE.Scene();camera=new THREE.PerspectiveCamera(58,1,.1,100);renderer=new THREE.WebGLRenderer({antialias:true,powerPreference:"high-performance"});renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.08;renderer.setPixelRatio(Math.min(devicePixelRatio,QUALITY[quality].pixel));container.innerHTML="";container.appendChild(renderer.domElement);controls();build();resize();window.addEventListener("resize",resize);animate(performance.now());console.log("EGS 3D: escena inicializada")}\nfunction start(){running=true;last=performance.now();log("Simulación iniciada")}\nfunction setScenario(v){active=v;build();running=true}\nfunction setCameraMode(v){mode=v;if(v==="first"){fp={x:0,y:1.65,z:9,yaw:Math.PI,pitch:0};log("Primera persona: WASD + mouse")}else{orbitCam();log("Cámara orbital")}}\nfunction setQuality(v){quality=QUALITY[v]?v:"media";renderer.setPixelRatio(Math.min(devicePixelRatio,QUALITY[quality].pixel));build();log("Calidad "+quality)}\nfunction reset(){build();running=true}\nfunction action(a){\n if(a==="recognition"){state.score+=5;log("Reconocimiento completado")}\n if(a==="open_access"){if(objects.door)objects.door.rotation.y=-Math.PI*.48;state.temperature+=28;state.oxygen=Math.min(20.9,state.oxygen+.3);state.smoke=Math.max(0,state.smoke-5);state.visibility=Math.min(100,state.visibility+4);log("Acceso abierto: cambió el flujo")}\n if(a==="open_window"){if(objects.window)objects.window.position.y=3;state.temperature+=38;state.oxygen=Math.min(20.9,state.oxygen+.55);state.smoke=Math.max(0,state.smoke-10);state.visibility=Math.min(100,state.visibility+8);log("Ventana abierta: cambió ventilación")}\n if(a==="ventilate"){state.smoke=Math.max(0,state.smoke-14);state.visibility=Math.min(100,state.visibility+12);state.oxygen=Math.min(20.9,state.oxygen+.45);state.temperature+=24;log("Ventilación ejecutada")}\n if(a==="cooling"){waterBurst();state.temperature=Math.max(40,state.temperature-115);state.smoke=Math.max(0,state.smoke-6);state.visibility=Math.min(100,state.visibility+6);fires.forEach(g=>g.scale.setScalar(.6));state.score+=8;log("Agua aplicada; disminuyó energía térmica")}\n if(a==="search"){if(objects.victim)objects.victim.material.color.set(0xffd166);state.score+=5;log("Búsqueda: víctima localizada")}\n if(a==="protect_exposure"){state.score+=6;log("Exposición protegida")}\n if(a==="isolate"){state.score+=6;log("Riesgos aislados")}\n if(a==="attack_vehicle"){waterBurst();fires.forEach(g=>g.scale.setScalar(.45));state.temperature=Math.max(50,state.temperature-130);state.smoke=Math.max(0,state.smoke-12);log("Ataque al foco vehicular")}\n if(a==="stabilize"){state.score+=8;objects.stabilized=true;log("Vehículo estabilizado")}\n if(a==="access_victim"){state.score+=objects.stabilized?8:-8;log(objects.stabilized?"Acceso creado con vehículo estabilizado":"Acceso creado sin estabilización previa")}\n if(a==="extricate"){if(objects.victim){objects.victim.position.x+=2.2;objects.victim.material.color.set(0xffd166)}state.score+=objects.stabilized?10:-10;log("Extricación ejecutada")}\n if(a==="phen_rollover"){state.temperature=430;state.smoke=72;state.visibility=30;fires.forEach(g=>g.scale.set(1.8,.35,1.8));log("Rollover: llamas en capa superior")}\n if(a==="phen_flashover"){state.temperature=690;state.smoke=90;state.visibility=9;for(let i=0;i<5;i++)fire([-4+i*2,.25,-1+Math.random()*2],.85);log("Flashover: transición rápida a combustión generalizada")}\n if(a==="phen_backdraft"){state.oxygen=15.5;state.smoke=96;state.visibility=5;state.temperature=360;if(objects.door)objects.door.rotation.y=-Math.PI*.48;setTimeout(()=>{for(let i=0;i<6;i++)fire([-3+i*1.2,.3,1.5],1.1);state.temperature=760;hud()},800);log("Demostración educativa: ventilación súbita con gases calientes")}\n if(a==="phen_smoke"){state.smoke=98;state.visibility=3;for(let i=0;i<4;i++)fire([-2+i*1.3,.5,0],.7);state.score-=2;log("Demostración visual de ignición rápida de mezcla de gases")}\n hud()\n}\nfunction finish(){running=false;alert(`Simulación finalizada · Puntaje ${Math.max(0,Math.min(100,Math.round(state.score)))}/100 · Tiempo ${fmt(elapsed)}`)}\nwindow.EGS3D={init,start,setScenario,setCameraMode,setQuality,reset,action,finish};\n'
}

for rel,text in FILES.items():
    p=ROOT/rel
    if p.exists():
        stamp=datetime.now().strftime("%Y%m%d_%H%M%S")
        shutil.copy2(p,BACKUP/f"{p.name}.{stamp}.bak")
    p.parent.mkdir(parents=True,exist_ok=True)
    p.write_text(text,encoding="utf-8")
    print("[OK]",rel)

